package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.nio.charset.Charset;
import java.nio.charset.CharsetEncoder;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.jsoup.Jsoup;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.parser.Tag;
import org.jsoup.select.Elements;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class Document_title_TriageGen2Test {

    private Document document;

    @Before
    public void setUp() {
        document = Document.createShell("");
    }

    @Test
    public void testTitleWithValidTitleTag() {
        Element titleEl = document.titleElement();
        titleEl.text("Example Title");
        Assert.assertEquals("Example Title", document.title());
    }

    @Test
    public void testTitleWithWhitespaceTitleTag() {
        Element titleEl = document.titleElement();
        titleEl.text("  Example Title  ");
        Assert.assertEquals("Example Title", document.title());
    }

    @Test
    public void testTitleWithNoTitleTag() {
        Assert.assertEquals("", document.title());
    }

    @Test
    public void testTitleWithNullDocument() {
        Document nullDocument = null;
        Assert.assertNull(nullDocument.title());
    }

    @Test
    public void testTitleWithMultipleTitleTags() {
        Element firstTitleEl = document.titleElement();
        firstTitleEl.appendElement("title").text("Second Title");
        Assert.assertEquals("Example Title", document.title());
    }

    @Test
    public void testTitleWithEmptyTitleTag() {
        Element titleEl = document.titleElement();
        titleEl.text("");
        Assert.assertEquals("", document.title());
    }

    @Test
    public void testTitleWithNewlineInTitle() {
        Element titleEl = document.titleElement();
        titleEl.text("Example\nTitle");
        Assert.assertEquals("Example\nTitle", document.title());
    }

    @Test
    public void testTitleWithTabInTitle() {
        Element titleEl = document.titleElement();
        titleEl.text("Example\tTitle");
        Assert.assertEquals("Example\tTitle", document.title());
    }

    @Test
    public void testTitleWithNullContentInTitleTag() {
        Element titleEl = document.titleElement();
        titleEl.text(null);
        Assert.assertEquals("", document.title());
    }
}
